local orderKey = KEYS[1]
local clOrderId = ARGV[1]

-- 检查订单是否已存在
if redis.call('EXISTS', orderKey) == 1 then
    return 0  -- 已存在
end

-- 写入订单信息
redis.call('HMSET', orderKey,
        'clOrderId', clOrderId,
        'market', ARGV[2],
        'securityId', ARGV[3],
        'side', ARGV[4],
        'qty', ARGV[5],
        'price', ARGV[6],
        'shareholderId', ARGV[7],
        'status', ARGV[8]
)

-- 设置订单状态缓存
redis.call('SET', 'order:status:' .. clOrderId, ARGV[8])

return 1  -- 成功